    float grow = smoothstep(0.0, 0.5, pre);
    float collapse = tau < tb ? 1.0 : exp(-(tau - tb) / 0.45);
    h += amp * prof * grow * mix(0.25, 1.0, collapse);
    // spilling lip: white on the crest top around the break, then the collapsing roller
