    mat3 R = bRotY(aPoseC.x) * bRotX(aPoseB.x);
    p = uNeck + R * (p - uNeck) + vec3(0.0, 0.0, aPoseB.y); n = R * n;
  } else if (part > 4.5 && part < 5.5) {      // legs: alternate swing, tucked in flight
